/* Einbindung: Die Einträge werden an blsItems() angehängt (wie die Schweizer Daten), gleichnamige Lebensmittel aus BLS/CH bleiben vorrangig.
   Geschätzte Mikros (Bitmaske "geschaetzt_maske") erscheinen wie bei den Online-Schätzungen mit ≈ und der Quellenangabe. */
(function(){
  if(typeof blsItems !== "function" || !window.NW_OFF2 || !Array.isArray(NW_OFF2.rows)) return;
  const baseBls = blsItems, baseDbName = dbName;
  blsItems = function(){
    const list = baseBls();
    if(list && !list._off2){
      list._off2 = true;
      const F = NW_OFF2.meta.felder, ix = n => F.indexOf(n);
      const MK = NW_OFF2.meta.mikro_reihenfolge, GR = NW_OFF2.meta.gruppen;
      const keys = ALL_KEYS.map(k => [k, ix(k)]).filter(x => x[1] >= 0);
      const have = new Set(list.map(it => it._s));
      NW_OFF2.rows.forEach(function(r){
        const s = normalize(r[0]);
        if(have.has(s)) return;
        const per100 = {}, miss = [];
        keys.forEach(([k, j]) => { per100[k] = r[j] || 0; });
        MK.forEach(k => { if(r[ix(k)] === null) miss.push((MICROS.find(m => m[0] === k) || [k, k])[1]); });
        const mask = r[ix("geschaetzt_maske")], estKeys = MK.filter((k, i) => (mask >> i) & 1);
        const grp = GR[r[ix("gruppe_idx")]] || "";
        list.push({id:"O"+r[1], name:r[0], cat:"bls", isDrink:false, per100, portions:[], cf:0, src:"Open Food Facts", isBLS:false, isOFF2:true, blsGroup:"OFF",
          missing:miss, labelMicros:r[ix("anzahl_mikros")], code:r[1], _s:s, _c:compact(r[0]), _w:s.split(/[^a-z0-9]+/).filter(w => w.length >= 5), rank:1e6,
          est: estKeys.length ? "Durchschnittswerte für „" + grp + "“ (Open Food Facts)" : undefined, estV: estKeys.length ? 2 : undefined, estKeys: estKeys});
      });
    }
    return list;
  };
  dbName = function(it){ return it && it.isOFF2 ? "Open Food Facts" : baseDbName(it); };
})();
